from decimal import Decimal, ROUND_HALF_UP

CENT = Decimal("0.01")
STANDARD_SHIPPING = Decimal("4.99")
EXPRESS_SHIPPING = Decimal("12.50")
FREE_SHIPPING_THRESHOLD = Decimal("100.00")
TAX_RATES = {"CA": Decimal("0.0825"), "NY": Decimal("0.08875"), "OR": Decimal("0")}
COUPONS = {"SAVE10": Decimal("0.10"), "SAVE20": Decimal("0.20")}
STATUSES = {"pending", "paid", "shipped", "cancelled"}


def money(value):
    amount = Decimal(str(value))
    if not amount.is_finite():
        raise ValueError("amount must be finite")
    return amount.quantize(CENT, rounding=ROUND_HALF_UP)


def validate_item(item):
    if not isinstance(item.get("sku"), str) or not item["sku"].strip():
        raise ValueError("sku is required")
    quantity = item.get("quantity")
    if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity < 1:
        raise ValueError("quantity must be a positive integer")
    price = money(item.get("unit_price", "-1"))
    if price < 0:
        raise ValueError("unit price must be nonnegative")
    return {"sku": item["sku"].strip(), "quantity": quantity, "unit_price": price}


def line_total(item):
    valid = validate_item(item)
    return money(valid["unit_price"] * valid["quantity"])


def calculate_subtotal(items):
    return money(sum((line_total(item) for item in items), Decimal("0")))


def discount_rate(coupon):
    code = (coupon or "").strip().upper()
    if code and code not in COUPONS:
        raise ValueError("unknown coupon")
    return COUPONS.get(code, Decimal("0"))


def calculate_discount(subtotal, coupon=None):
    amount = money(subtotal)
    if amount < 0:
        raise ValueError("subtotal must be nonnegative")
    return money(amount * discount_rate(coupon))


def calculate_shipping(subtotal, express=False):
    amount = money(subtotal)
    if amount < 0:
        raise ValueError("subtotal must be nonnegative")
    if express:
        return EXPRESS_SHIPPING
    if amount >= FREE_SHIPPING_THRESHOLD:
        return Decimal("0.00")
    return STANDARD_SHIPPING


def calculate_tax(taxable_amount, region):
    if region not in TAX_RATES:
        raise ValueError("unsupported tax region")
    amount = money(taxable_amount)
    if amount < 0:
        raise ValueError("taxable amount must be nonnegative")
    return money(amount * TAX_RATES[region])


def calculate_order_total(items, region="OR", coupon=None, express=False):
    subtotal = calculate_subtotal(items)
    discount = calculate_discount(subtotal, coupon)
    discounted = money(subtotal - discount)
    shipping = calculate_shipping(discounted, express)
    tax = calculate_tax(discounted, region)
    return money(discounted + shipping + tax)


def make_order(order_id, items, region="OR", coupon=None, express=False):
    if not isinstance(order_id, str) or not order_id.strip():
        raise ValueError("order id is required")
    normalized = [validate_item(item) for item in items]
    if not normalized:
        raise ValueError("an order must contain at least one item")
    total = calculate_order_total(normalized, region, coupon, express)
    return {"order_id": order_id.strip(), "items": normalized, "region": region,
            "coupon": coupon, "express": bool(express), "total": total, "status": "pending"}


def transition_order(order, new_status):
    allowed = {"pending": {"paid", "cancelled"}, "paid": {"shipped", "cancelled"},
               "shipped": set(), "cancelled": set()}
    old_status = order.get("status")
    if old_status not in STATUSES or new_status not in allowed[old_status]:
        raise ValueError("invalid status transition")
    result = dict(order)
    result["status"] = new_status
    return result


def receipt_lines(order):
    lines = ["Order " + order["order_id"]]
    for item in order["items"]:
        lines.append(f'{item["sku"]}: {item["quantity"]} x {money(item["unit_price"])}')
    lines.append("Total: " + str(money(order["total"])))
    return lines


def summarize_orders(orders):
    totals = {status: Decimal("0.00") for status in sorted(STATUSES)}
    count = 0
    for order in orders:
        status = order.get("status")
        if status not in totals:
            raise ValueError("invalid order status")
        totals[status] = money(totals[status] + money(order["total"]))
        count += 1
    return {"count": count, "totals": totals}


def requote_order(order, coupon=None):
    result = dict(order)
    result["coupon"] = coupon
    result["total"] = calculate_order_total(order["items"], order["region"], coupon, order["express"])
    return result


# Operations notes:
# Prices are rounded before quantity multiplication.
# Tax applies to discounted merchandise, excluding shipping.
# The free shipping threshold applies after discounts.
# Express delivery always retains its separate shipping charge.
# Order state changes produce a new dictionary.
# Summaries accept a one-pass iterable of orders.
# Cancelled orders remain available to status summaries.
# Coupon codes are case-insensitive after trimming whitespace.

